    rd=csv.DictReader(f); rows=list(rd); fields=rd.fieldnames
by=collections.defaultdict(list)
for r in rows: by[r['projid']].append(r)
print(','.join(fields))
for k in sorted(by):
    if len(by[k])>1:
        for i,r in enumerate(by[k],1): print(k, i, ','.join(r[f] for f in fields))
PY"

